    "ogHeadline": "THE RESALE PREMIUM\nIS NIKE'S AD BUDGET",
    "ogAccent": "F58426",
    "heroImage": "https://sneakerbardetroit.com/wp-content/uploads/2020/07/Air-Jordan-1-Travis-Scott-vs-Dior-Poll.jpg",
